    match &res.fills {
        Some(f) => {
            let v = f.lcl_cache as f64 / res.rts.max(1) as f64;
            if v < 0.01 {
                format!("{v:.4}")
            } else {
                format!("{v:.3}")
            }
        }
        None => "-".to_string(),
    }
}
