                assert_eq!(seq, i, "pool stream order broken");
                let idx = ((node as usize - base) / CACHE_LINE_SIZE) as u32;
                let desc = Desc {
                    pool_id: pool_id.as_u32(),
                    buf_idx: idx,
                };
