//! Consuming endpoint: [`Consumer`] finds the oldest committed
//! slot by the seq word at its front, the [`ReadSlot`] guard
//! reads the body behind it in place and releases through the
//! same word.

use core::marker::PhantomData;
use core::ops::Deref;
use core::sync::atomic::{AtomicU32, Ordering};
use zerocopy::{FromBytes, Immutable, KnownLayout};

use super::{Header, Seq, check_body_type, seq_of, slot_parts};
use crate::{Empty, USER_WORDS};

/// The consuming endpoint: `reserve_slot_with` the oldest
/// committed slot, read in place, `release`.
pub struct Consumer<'a> {
    /// The ring's control block.
    header: &'a Header,
    /// Base of the slot array.
    slots: *mut u8,
    /// Geometry snapshot (see [`Ring`](super::Ring)).
    slot_size: u32,
    /// Geometry snapshot: release stores `pos + capacity`.
    capacity: u32,
    /// Slot-position mask (`capacity - 1`).
    mask: u32,
    _region: PhantomData<&'a [u8]>,
}

// SAFETY: the handle owns the consumer role. See the Producer
// Send rationale.
unsafe impl Send for Consumer<'_> {}

impl<'a> Consumer<'a> {
    /// Build the handle from [`Ring::split`](super::Ring::split)'s
    /// geometry snapshot.
    pub(super) fn new(
        header: &'a Header,
        slots: *mut u8,
        slot_size: u32,
        capacity: u32,
        mask: u32,
    ) -> Self {
        Consumer {
            header,
            slots,
            slot_size,
            capacity,
            mask,
            _region: PhantomData,
        }
    }

    /// The header's app-owned scratch line, the v0 endpoints'
    /// `user()` contract.
    pub fn user(&self) -> &[AtomicU32; USER_WORDS] {
        &self.header.user
    }

    /// Reserve the oldest unread slot as a `&T`, applying an
    /// injected wait policy: retry until a message arrives or
    /// the policy gives up, then [`Empty`].
    ///
    /// - The slot at `c` is committed when its seq is
    ///   `c + M + 1`. Anything else reads as Empty, never as a
    ///   readable slot.
    /// - Only `consumer_idx` (ours, loaded once) and the slot's
    ///   own line are touched.
    /// - Guard semantics as v0's [`ReadSlot`](crate::ReadSlot):
    ///   one reservation at a time, drop without release
    ///   re-delivers the same slot.
    /// - `on_empty` is called after each failed attempt with
    ///   the attempt count (0-based, saturating). Returning
    ///   `false` gives up. Pass `|_| false` for a single
    ///   non-blocking probe.
    pub fn reserve_slot_with<T>(
        &mut self,
        mut on_empty: impl FnMut(u32) -> bool,
    ) -> Result<ReadSlot<'_, T>, Empty>
    where
        T: FromBytes + KnownLayout + Immutable,
    {
        check_body_type::<T>(self.slot_size);
        // Ours alone: the producer never reads or writes it.
        let c = self.header.consumer_idx.load(Ordering::Relaxed);
        let (slot, body) = slot_parts(self.slots, c, self.mask, self.slot_size);
        let expected = seq_of(c.wrapping_add(self.capacity).wrapping_add(1));
        let mut attempt = 0u32;
        loop {
            // Acquire pairs with the producer's Release commit:
            // observing expected means the fill is visible.
            if slot.seq.load(Ordering::Acquire) == expected {
                break;
            }
            if !on_empty(attempt) {
                return Err(Empty);
            }
            attempt = attempt.saturating_add(1);
        }
        Ok(ReadSlot {
            header: self.header,
            seq: &slot.seq,
            msg: body as *const T,
            next_idx: c.wrapping_add(1),
            released_seq: seq_of(c.wrapping_add(self.capacity)),
            _slot: PhantomData,
        })
    }
}

/// A reserved read slot: `Deref` to read the message, then
/// [`release`](ReadSlot::release).
pub struct ReadSlot<'c, T> {
    /// The ring's control block (for the consumer_idx store).
    header: &'c Header,
    /// The reserved slot's seq word (for the release store).
    seq: &'c Seq,
    /// The slot body, viewed as the message type. Raw on
    /// purpose, see v0's `ReadSlot`.
    msg: *const T,
    /// Value `consumer_idx` takes on release.
    next_idx: u32,
    /// Value the seq takes on release (`pos + capacity`):
    /// claimable again one lap later.
    released_seq: super::SeqInt,
    /// Owns the `&'c` borrow of the consumer.
    _slot: PhantomData<&'c T>,
}

impl<T> Deref for ReadSlot<'_, T> {
    type Target = T;
    /// Read access to the in-slot message.
    fn deref(&self) -> &T {
        // SAFETY: msg is in-bounds and aligned (check_body_type
        // against the body's offset in a line-aligned slot), any
        // byte pattern is a valid T (FromBytes bound), and the
        // seq protocol gives this guard read access until
        // release.
        unsafe { &*self.msg }
    }
}

impl<T> ReadSlot<'_, T> {
    /// Free the slot for reuse.
    ///
    /// - `consumer_idx` first (`Relaxed`, consumer-private
    ///   resume state), the seq store last (`Release`, the
    ///   protocol-visible handoff the producer acquires).
    pub fn release(self) {
        self.header
            .consumer_idx
            .store(self.next_idx, Ordering::Relaxed);
        self.seq.store(self.released_seq, Ordering::Release);
    }
}

//! Zero-copy no_std SPSC ring buffer over a caller-provided
//! memory region, per [notes/ring-buffer-design.md]:
//!
//! - One `#[repr(C)]` [`Header`] spanning four cache lines
//!   (immutable geometry, producer index, consumer index, app
//!   user words), followed by M slots of N bytes.
//! - Indices are free-running `AtomicU32`s, masked only at slot
//!   access; full is `p - c == M`, no sacrificial slot.
//! - Messages move in place: the producer writes through a
//!   [`WriteSlot`] `&mut T`, the consumer reads through a
//!   [`ReadSlot`] `&T` — zerocopy traits bound `T`, no
//!   serialization step. Each side reserves at most one slot at
//!   a time; the guard holds the endpoint borrow until commit /
//!   release (or drop).
//! - The SPSC protocol lives in the `spsc` module; a
//!   multi-producer sibling, [`MpscRing`], lives in the
//!   `mpsc` module (gated on CAS support) — see its module
//!   docs for the claim/seq protocol and closure-send API.
//!   Primitive modules hold versioned sibling implementations
//!   (`spsc::v0`, …) behind per-module default-version
//!   re-exports; this crate root re-exports the defaults.
//!
//! [notes/ring-buffer-design.md]: https://github.com/winksaville/zc-ring-x1/blob/main/notes/ring-buffer-design.md

#![cfg_attr(not(test), no_std)]

use core::mem::{align_of, size_of};
use core::sync::atomic::AtomicU32;

// The MPSC ring needs CAS (the claim), so it is gated; the
// SPSC ring protocol stays load/store-only. (The pool's
// free-stack also uses CAS and predates the gate — see
// notes/bugs.md.)
#[cfg(target_has_atomic = "32")]
pub mod mpsc;
pub mod policy;
pub mod pool;
mod registry;
pub mod spsc;

#[cfg(target_has_atomic = "32")]
pub use mpsc::{MpscConsumer, MpscHeader, MpscProducer, MpscReadSlot, MpscRing, mpsc_region_size};
pub use pool::{BufSlot, Exhausted, Pool, PoolHeader, PoolResolver};
pub use registry::{Desc, PoolId, PoolRegistry, RegistryError};
pub use spsc::{Consumer, Header, Producer, ReadSlot, Ring, WriteSlot};

/// Cache-line size the layout is built around.
///
/// - Slot size must be a multiple of this; slots and the region
///   itself must be aligned to it.
pub const CACHE_LINE_SIZE: usize = 64;

/// Number of `AtomicU32` words in the header's app-owned
/// `user` line.
pub const USER_WORDS: usize = 16;

/// `reserve_slot_with` / `send_with` failed: every slot holds
/// an uncommitted-or-unread message.
///
/// - Shared by the ring primitives (SPSC reserve, MPSC send) —
///   defined in the crate core so no primitive depends on a
///   sibling's version module for its error type.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Full;

/// `reserve_slot_with` failed: no unread messages.
///
/// - Shared by the ring primitives' consumer endpoints — see
///   [`Full`] for why it lives in the crate core.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Empty;

/// Cache-line-aligned wrapper granting its field sole
/// ownership of the line.
///
/// - `repr(align(N))` accepts only an integer literal — it
///   cannot name [`CACHE_LINE_SIZE`] — so the `64` is written out
///   and a const assert ties them back together.
#[repr(C, align(64))]
struct CacheAligned<T>(T);

const _: () = assert!(align_of::<CacheAligned<AtomicU32>>() == CACHE_LINE_SIZE);

impl<T> core::ops::Deref for CacheAligned<T> {
    type Target = T;
    /// Access the wrapped value.
    fn deref(&self) -> &T {
        &self.0
    }
}

/// Errors from region validation — [`Ring::init`] /
/// [`Ring::attach`] and [`Pool::init`] / [`Pool::attach`].
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Error {
    /// Region is not [`CACHE_LINE_SIZE`]-aligned.
    Misaligned,
    /// Region is smaller than header + slots/buffers.
    TooSmall,
    /// Slot size is zero or not a [`CACHE_LINE_SIZE`] multiple.
    BadSlotSize,
    /// Capacity is zero, not a power of two, over the ring's
    /// cap, or under its floor (the MPSC v0 ring's is 2).
    BadCapacity,
    /// Pool: buffer size is zero or not a [`CACHE_LINE_SIZE`]
    /// multiple.
    BadBufSize,
    /// Pool: buffer count is zero or `u32::MAX` (the
    /// free-stack NIL sentinel).
    BadBufCount,
    /// Attach: magic mismatch — not a region of the expected
    /// kind.
    BadMagic,
    /// Attach: layout version mismatch.
    BadLayoutVersion,
    /// Attach: region built with a different [`CACHE_LINE_SIZE`].
    BadCacheLine,
}

/// Check `T` fits a slot; called once per `reserve_slot_with`
/// (both endpoints).
///
/// - Panics on a type-geometry mismatch — that is a programming
///   error, not a runtime condition.
fn check_type<T>(slot_size: u32) {
    assert!(size_of::<T>() <= slot_size as usize, "T larger than slot");
    assert!(
        core::mem::align_of::<T>() <= CACHE_LINE_SIZE,
        "T alignment exceeds slot alignment"
    );
}

/// Non-panicking form of [`check_type`], for descriptor
/// resolve — there the pool compared against is selected by
/// untrusted input, which must not be able to select a panic.
fn type_fits<T>(slot_size: u32) -> bool {
    size_of::<T>() <= slot_size as usize && core::mem::align_of::<T>() <= CACHE_LINE_SIZE
}

/// Pointer to the slot for free-running index `idx`.
///
/// - Returned range is `slot_size` bytes, cache-line aligned
///   (base is, and slot_size is a line multiple).
fn slot_ptr(slots: *mut u8, idx: u32, mask: u32, slot_size: u32) -> *mut u8 {
    let pos = (idx & mask) as usize;
    // SAFETY: pos < capacity, so the offset is inside the slot
    // array validated at init/attach.
    unsafe { slots.add(pos * slot_size as usize) }
}

