92	        let mut attempt = 0u32;
93	        loop {
94	            // Acquire pairs with the consumer's Release release:
95	            // observing `p` means its reads of the previous lap
96	            // are done.
97	            if slot.seq.load(Ordering::Acquire) == claimable {
98	                break;
99	            }
100	            if !on_full(attempt) {
101	                return Err(Full);
102	            }
103	            attempt = attempt.saturating_add(1);
104	        }
105	        Ok(WriteSlot {
106	            header: self.header,
107	            seq: &slot.seq,
108	            msg: body as *mut T,
109	            next_idx: p.wrapping_add(1),
