332	/// Check `T` fits a slot's body, called once per
333	/// `reserve_slot_with` (both endpoints).
334	///
335	/// - The body is the slot behind [`SLOT_HEADER_BYTES`], so the
336	///   size bound is that much smaller than the slot and the
337	///   alignment bound is the header's size, the body's offset
338	///   in a line-aligned slot.
339	/// - Panics on a mismatch, a programming error rather than a
340	///   runtime condition, as the crate's `check_type` does.
341	fn check_body_type<T>(slot_size: u32) {
342	    assert!(
343	        size_of::<T>() <= slot_size as usize - SLOT_HEADER_BYTES,
344	        "T larger than the slot body"
345	    );
346	    assert!(
347	        align_of::<T>() <= SLOT_HEADER_BYTES,
348	        "T alignment exceeds the slot body's"
349	    );
350	}
