352	/// The slot header and body for free-running index `idx`.
353	///
354	/// - Returns the slot's `SlotHeader` and the body pointer
355	///   behind it.
356	fn slot_parts<'s>(
357	    slots: *mut u8,
358	    idx: u32,
359	    mask: u32,
360	    slot_size: u32,
361	) -> (&'s SlotHeader, *mut u8) {
362	    let slot = crate::slot_ptr(slots, idx, mask, slot_size);
363	    // SAFETY: the slot is line-aligned and slot_size bytes, so
364	    // the header at its front is in bounds and aligned, and it
365	    // is atomic state shared by design. The body pointer is in
366	    // bounds since SLOT_HEADER_BYTES < CACHE_LINE_SIZE <=
367	    // slot_size.
368	    unsafe { (&*(slot as *const SlotHeader), slot.add(SLOT_HEADER_BYTES)) }
