256	        let flavor = flavor.as_str();
257	        RecvProbes {
258	            phase: TProbe::new(&format!("{flavor} {side} recv (reserve+release)")),
259	            spin: TProbe::new(&format!("{flavor} {side} recv spin (wait only)")),
260	            attempts: TProbe::new_counts(&format!("{flavor} {side} recv attempts")),
