265	/// One instrumented receive: `reserve` performs the endpoint's
266	/// reserve/read/release under a spin policy that must stamp
267	/// `spin_start` on its first failed attempt and keep `attempts`
268	/// current, then returns the received value. Records the phase
269	/// (and, when a wait happened, spin time + attempts) into
270	/// `probes`, unless the value is [`STOP`], which passes
271	/// through unrecorded.
272	fn instrumented_recv(
273	    probes: &mut RecvProbes,
274	    reserve: impl FnOnce(&mut u32, &mut u64) -> u64,
275	) -> u64 {
276	    let mut attempts: u32 = 0;
277	    let mut spin_start: u64 = 0;
278	    let s = ticks::read_ticks();
279	    let v = reserve(&mut attempts, &mut spin_start);
280	    let spin_end = if attempts > 0 { ticks::read_ticks() } else { 0 };
281	    let e = ticks::read_ticks();
282	    if v == STOP {
283	        return v;
284	    }
285	    probes.phase.record(e.wrapping_sub(s));
286	    if attempts > 0 {
287	        probes.spin.record(spin_end.wrapping_sub(spin_start));
288	        probes.attempts.record(attempts as u64);
289	    }
290	    v
291	}
