303	) -> CellResult {
304	    match pin {
305	        Some((main_cpu, _)) => pin_to_cpu(main_cpu),
306	        None => unpin_current(),
307	    }
308	    #[cfg(target_os = "linux")]
309	    let fills = Fills::open();
310	    let worker = pin.map(|(_, w)| w);
311	    let probes = match flavor {
312	        Flavor::SpscV0 => run_spsc_v0(dur, worker, depth),
313	        Flavor::SpscV1 => run_spsc_v1(dur, worker, depth),
314	        Flavor::SpscV2 => run_spsc_v2(dur, worker, depth),
