316	        Flavor::MpscV1 => run_mpsc_v1(dur, worker, depth),
317	    };
318	    #[cfg(target_os = "linux")]
319	    let fills = fills.and_then(Fills::finish);
320	    #[cfg(not(target_os = "linux"))]
321	    let fills = None;
322	    let rts = probes[0].count();
323	    CellResult { probes, rts, fills }
