355	                    ));
356	                    loop {
357	                        let v = instrumented_recv(&mut recv, |attempts, spin_start| {
358	                            let slot = req_rx
359	                                .reserve_slot_with::<u64>(|a| {
360	                                    if a == 0 {
361	                                        *spin_start = ticks::read_ticks();
362	                                    }
363	                                    *attempts = a + 1;
364	                                    core::hint::spin_loop();
365	                                    true
366	                                })
367	                                .expect("spin never gives up");
368	                            let v = *slot;
369	                            slot.release();
370	                            v
371	                        });
372	                        if v == STOP {
373	                            break;
374	                        }
375	                        let s = ticks::read_ticks();
376	                        let mut slot = resp_tx
377	                            .reserve_slot_with::<u64>(spin)
378	                            .expect("spin never gives up");
379	                        *slot = v;
380	                        slot.commit();
381	                        send_probe.record(ticks::read_ticks().wrapping_sub(s));
382	                    }
383	                    (recv, send_probe)
384	                });
385	
386	                let mut send_probe =
387	                    TProbe::new(&format!("{} main send (reserve+commit)", $flavor.as_str()));
