389	                drive(
390	                    dur,
391	                    |v| {
392	                        let s = ticks::read_ticks();
393	                        let mut slot = req_tx
394	                            .reserve_slot_with::<u64>(spin)
395	                            .expect("spin never gives up");
396	                        *slot = v;
