399	                    },
400	                    || {
401	                        instrumented_recv(&mut recv, |attempts, spin_start| {
402	                            let slot = resp_rx
403	                                .reserve_slot_with::<u64>(|a| {
404	                                    if a == 0 {
405	                                        *spin_start = ticks::read_ticks();
406	                                    }
407	                                    *attempts = a + 1;
408	                                    core::hint::spin_loop();
409	                                    true
410	                                })
411	                                .expect("spin never gives up");
412	                            let v = *slot;
413	                            slot.release();
414	                            v
415	                        })
416	                    },
417	                );
