1	//! Producing endpoint: [`Producer`] claims the next slot of its
2	//! current segment by the seq word at its front, and the
3	//! [`WriteSlot`] guard writes the body in place and commits
4	//! through the same word, switching segments when the next slot
5	//! is taken.
6	
7	use core::marker::PhantomData;
8	use core::ops::{Deref, DerefMut};
9	use core::sync::atomic::Ordering;
10	use zerocopy::{FromBytes, IntoBytes, KnownLayout};
11	
12	use super::{MAX_SEGMENTS, MOVED, SEG_SHIFT, Segments, check_body_type, seq_of};
13	use crate::Full;
14	
15	/// The producer's private state, held apart from the handle so a
16	/// guard can borrow it without naming the region's lifetime.
17	pub(super) struct ProducerState {
18	    /// Geometry and segment addresses.
19	    pub(super) segs: Segments,
20	    /// The segment being written.
21	    pub(super) cur: u32,
22	    /// Free-running position in `cur`.
23	    pub(super) pos: u32,
24	    /// Where each segment was left, the position a reuse starts
25	    /// at. The consumer keeps the same values of its own.
26	    pub(super) resume: [u32; MAX_SEGMENTS as usize],
27	    /// One bit per segment, flipped on each take: free where it
28	    /// agrees with the consumer's give-back word.
29	    pub(super) taken: u32,
30	    /// The slot at `pos` was seen claimable and so still is: only
31	    /// the producer turns claimable into anything else.
32	    pub(super) claimable: bool,
33	}
34	
35	/// The producing endpoint: `reserve_slot_with`, write in place,
36	/// `commit`.
37	pub struct Producer<'a> {
38	    /// Private state, borrowed by each guard.
39	    pub(super) st: ProducerState,
40	    _region: PhantomData<&'a [u8]>,
41	}
42	
43	// SAFETY: the handle owns the producer role. The shared state it
44	// touches (slot seqs, the give-back word) is atomic, and slot
45	// writes are handed off with Release/Acquire ordering.
46	unsafe impl Send for Producer<'_> {}
47	
48	impl<'a> Producer<'a> {
49	    /// Start in segment 0, held as taken.
50	    pub(super) fn new(segs: Segments) -> Self {
51	        Producer {
52	            st: ProducerState {
53	                segs,
54	                cur: 0,
55	                pos: 0,
56	                resume: [0; MAX_SEGMENTS as usize],
57	                taken: 1,
58	                claimable: false,
59	            },
60	            _region: PhantomData,
61	        }
62	    }
63	
64	    /// Reserve the next free slot as a `&mut T`, applying an
65	    /// injected wait policy: retry until the slot frees up or the
66	    /// policy gives up, then [`Full`].
67	    ///
68	    /// - The slot at `p` is free when its seq is `p`, as v2's. A
69	    ///   slot the last commit already saw claimable is not loaded
70	    ///   again.
71	    /// - Full here means the current segment's next slot is still
72	    ///   unread and no segment was free at the last commit: the
73	    ///   ring waits in place as one ring does.
74	    /// - `T` must fit the slot body, `slot_size` less
75	    ///   [`SLOT_HEADER_BYTES`](super::SLOT_HEADER_BYTES), at an
76	    ///   alignment of at most that.
77	    /// - Guard semantics as v2's: one reservation at a time, drop
78	    ///   without commit abandons it.
79	    pub fn reserve_slot_with<T>(
80	        &mut self,
81	        mut on_full: impl FnMut(u32) -> bool,
82	    ) -> Result<WriteSlot<'_, T>, Full>
83	    where
84	        T: FromBytes + IntoBytes + KnownLayout,
85	    {
86	        let st = &mut self.st;
87	        check_body_type::<T>(st.segs.slot_size);
88	        let p = st.pos;
89	        if !st.claimable {
90	            let claimable = seq_of(p);
91	            let mut attempt = 0u32;
92	            loop {
93	                // Acquire pairs with the consumer's Release release:
94	                // observing `p` means its read of the slot is done.
95	                if st.segs.seq(st.cur, p).load(Ordering::Acquire) == claimable {
96	                    break;
97	                }
98	                if !on_full(attempt) {
99	                    return Err(Full);
100	                }
101	                attempt = attempt.saturating_add(1);
102	            }
103	            st.claimable = true;
104	        }
105	        let msg = st.segs.body(st.cur, p) as *mut T;
106	        Ok(WriteSlot {
107	            st,
108	            msg,
109	            _slot: PhantomData,
110	        })
111	    }
112	}
113	
114	/// A reserved write slot: `DerefMut` to write the message, then
115	/// [`commit`](WriteSlot::commit).
116	pub struct WriteSlot<'p, T> {
117	    /// The producer's state, for the commit and any switch.
118	    st: &'p mut ProducerState,
119	    /// The slot body, viewed as the message type.
120	    msg: *mut T,
121	    /// Owns the `&'p mut` borrow of the producer.
122	    _slot: PhantomData<&'p mut T>,
123	}
124	
125	impl<T> Deref for WriteSlot<'_, T> {
126	    type Target = T;
127	    /// Read access to the in-slot message.
128	    fn deref(&self) -> &T {
129	        // SAFETY: msg is in-bounds and aligned (check_body_type
130	        // against the body's offset in a line-aligned slot), any
131	        // byte pattern is a valid T (FromBytes bound at
132	        // reserve_slot_with), and the seq protocol gives this
133	        // guard exclusive slot access until commit.
134	        unsafe { &*self.msg }
135	    }
136	}
137	
138	impl<T> DerefMut for WriteSlot<'_, T> {
139	    /// Write access to the in-slot message.
140	    fn deref_mut(&mut self) -> &mut T {
141	        // SAFETY: as in deref. &mut self gives exclusivity of the
142	        // minted reference.
143	        unsafe { &mut *self.msg }
144	    }
145	}
146	
147	impl<T> WriteSlot<'_, T> {
148	    /// Publish the slot to the consumer.
149	    ///
150	    /// - Looks at the next slot first. Claimable: an ordinary
151	    ///   commit, and the next reserve skips its load.
152	    /// - Not claimable, the segment about to be full: with a free
153	    ///   segment, take it and commit with MOVED and its number,
154	    ///   so this message is the last in the old segment. With
155	    ///   none, commit plainly and let the next reserve wait.
156	    /// - The seq store is last (`Release`), after every private
157	    ///   update, the protocol-visible handoff.
158	    pub fn commit(self) {
159	        let st = self.st;
160	        let segs = st.segs;
161	        let p = st.pos;
162	        let next = p.wrapping_add(1);
163	        let slot = segs.seq(st.cur, p);
164	        let mut word = seq_of(p.wrapping_add(segs.capacity).wrapping_add(1));
165	        // At depth 1 the next slot is this one, still claimable
166	        // at `p`, so it never reads as claimable at `next`.
167	        st.claimable = segs.seq(st.cur, next).load(Ordering::Acquire) == seq_of(next);
168	        st.pos = next;
169	        if !st.claimable {
170	            let free = !(st.taken ^ segs.given().load(Ordering::Acquire)) & segs.all();
171	            if free != 0 {
172	                let k = free.trailing_zeros();
173	                st.taken ^= 1 << k;
174	                word |= MOVED | (k << SEG_SHIFT);
175	                st.resume[st.cur as usize] = next;
176	                st.cur = k;
177	                st.pos = st.resume[k as usize];
178	            }
179	        }
180	        slot.store(word, Ordering::Release);
181	    }
182	}

1	//! Consuming endpoint: [`Consumer`] finds the oldest committed
2	//! slot of its current segment by the seq word at its front, and
3	//! the [`ReadSlot`] guard reads the body in place and releases
4	//! through the same word, following the producer to the next
5	//! segment after a MOVED message.
6	
7	use core::marker::PhantomData;
8	use core::ops::Deref;
9	use core::sync::atomic::Ordering;
10	use zerocopy::{FromBytes, Immutable, KnownLayout};
11	
12	use super::{
13	    MAX_SEGMENTS, MOVED, SEG_MASK, SEG_SHIFT, SEQ_MASK, Segments, check_body_type, seq_of,
14	};
15	use crate::Empty;
16	
17	/// The consumer's private state, held apart from the handle so a
18	/// guard can borrow it without naming the region's lifetime.
19	pub(super) struct ConsumerState {
20	    /// Geometry and segment addresses.
21	    pub(super) segs: Segments,
22	    /// The segment being read.
23	    pub(super) cur: u32,
24	    /// Free-running position in `cur`.
25	    pub(super) pos: u32,
26	    /// Where each segment was left, the position a reuse starts
27	    /// at, the same values the producer keeps.
28	    pub(super) resume: [u32; MAX_SEGMENTS as usize],
29	    /// The give-back word's value: this side is its only writer.
30	    pub(super) given: u32,
31	}
32	
33	/// The consuming endpoint: `reserve_slot_with` the oldest
34	/// committed slot, read in place, `release`.
35	pub struct Consumer<'a> {
36	    /// Private state, borrowed by each guard.
37	    pub(super) st: ConsumerState,
38	    _region: PhantomData<&'a [u8]>,
39	}
40	
41	// SAFETY: the handle owns the consumer role. See the Producer
42	// Send rationale.
43	unsafe impl Send for Consumer<'_> {}
44	
45	impl<'a> Consumer<'a> {
46	    /// Start in segment 0, where the producer starts.
47	    pub(super) fn new(segs: Segments) -> Self {
48	        Consumer {
49	            st: ConsumerState {
50	                segs,
51	                cur: 0,
52	                pos: 0,
53	                resume: [0; MAX_SEGMENTS as usize],
54	                given: 0,
55	            },
56	            _region: PhantomData,
57	        }
58	    }
59	
60	    /// Reserve the oldest unread slot as a `&T`, applying an
61	    /// injected wait policy: retry until a message arrives or the
62	    /// policy gives up, then [`Empty`].
63	    ///
64	    /// - One load of the slot's word tells everything: its seq bits
65	    ///   at `c + M + 1` mean a message, and a MOVED bit with it
66	    ///   means the producer's last in this segment. Anything else
67	    ///   reads as Empty.
68	    /// - A MOVED word naming a segment the ring does not have reads
69	    ///   as Empty, failing toward Empty as the rings do.
70	    /// - Guard semantics as v2's: one reservation at a time, drop
71	    ///   without release re-delivers the same slot.
72	    pub fn reserve_slot_with<T>(
73	        &mut self,
74	        mut on_empty: impl FnMut(u32) -> bool,
75	    ) -> Result<ReadSlot<'_, T>, Empty>
76	    where
77	        T: FromBytes + KnownLayout + Immutable,
78	    {
79	        let st = &mut self.st;
80	        check_body_type::<T>(st.segs.slot_size);
81	        let c = st.pos;
82	        let expected = seq_of(c.wrapping_add(st.segs.capacity).wrapping_add(1));
83	        let seq = st.segs.seq(st.cur, c);
84	        let mut attempt = 0u32;
85	        let word = loop {
86	            // Acquire pairs with the producer's Release commit:
87	            // observing the committed seq means the fill is visible.
88	            let word = seq.load(Ordering::Acquire);
89	            if word & SEQ_MASK == expected
90	                && (word & MOVED == 0 || (word >> SEG_SHIFT) & SEG_MASK < st.segs.seg_count)
91	            {
92	                break word;
93	            }
94	            if !on_empty(attempt) {
95	                return Err(Empty);
96	            }
97	            attempt = attempt.saturating_add(1);
98	        };
99	        let msg = st.segs.body(st.cur, c) as *const T;
100	        Ok(ReadSlot {
101	            st,
102	            msg,
103	            word,
104	            _slot: PhantomData,
105	        })
106	    }
107	}
108	
109	/// A reserved read slot: `Deref` to read the message, then
110	/// [`release`](ReadSlot::release).
111	pub struct ReadSlot<'c, T> {
112	    /// The consumer's state, for the release and any switch.
113	    st: &'c mut ConsumerState,
114	    /// The slot body, viewed as the message type.
115	    msg: *const T,
116	    /// The committed word the reserve loaded.
117	    word: u32,
118	    /// Owns the `&'c mut` borrow of the consumer.
119	    _slot: PhantomData<&'c T>,
120	}
121	
122	impl<T> Deref for ReadSlot<'_, T> {
123	    type Target = T;
124	    /// Read access to the in-slot message.
125	    fn deref(&self) -> &T {
126	        // SAFETY: msg is in-bounds and aligned (check_body_type
127	        // against the body's offset in a line-aligned slot), any
128	        // byte pattern is a valid T (FromBytes bound), and the seq
129	        // protocol gives this guard read access until release.
130	        unsafe { &*self.msg }
131	    }
132	}
133	
134	impl<T> ReadSlot<'_, T> {
135	    /// Free the slot for reuse.
136	    ///
137	    /// - The released seq store comes first (`Release`), clearing
138	    ///   any MOVED bits, so a segment given back holds only
139	    ///   claimable seqs.
140	    /// - After a MOVED message: give the old segment back by
141	    ///   flipping its bit in the give-back word (`Release`), then
142	    ///   continue in the named segment where it was left.
143	    pub fn release(self) {
144	        let st = self.st;
145	        let segs = st.segs;
146	        let c = st.pos;
147	        let next = c.wrapping_add(1);
148	        segs.seq(st.cur, c)
149	            .store(seq_of(c.wrapping_add(segs.capacity)), Ordering::Release);
150	        st.pos = next;
151	        if self.word & MOVED != 0 {
152	            let k = (self.word >> SEG_SHIFT) & SEG_MASK;
153	            st.given ^= 1 << st.cur;
154	            st.resume[st.cur as usize] = next;
155	            segs.given().store(st.given, Ordering::Release);
156	            st.cur = k;
157	            st.pos = st.resume[k as usize];
158	        }
159	    }
160	}

