13	/// The message: a sequence number the consumer checks.
14	#[derive(FromBytes, IntoBytes, KnownLayout, Immutable)]
15	#[repr(C)]
16	struct Msg {
17	    seq: u64,
18	}
19	
20	/// One cache line of heap backing store, so a `Vec` of them is a
21	/// line-aligned region of any size.
22	#[derive(FromBytes, IntoBytes, KnownLayout, Immutable, Clone)]
23	#[repr(C, align(64))]
24	struct Line([u8; 64]);
25	
26	/// The depths every segment count runs at.
27	const DEPTHS: [u32; 4] = [1, 8, 64, 1024];
