32	/// Run `f` on a ring of `count` segments of `depth` one-line slots
33	/// over a pool holding exactly those segments.
34	fn with_ring<R>(count: u32, depth: u32, f: impl FnOnce(Producer<'_>, Consumer<'_>) -> R) -> R {
35	    let buf = segment_size(64, depth);
36	    let bytes = size_of::<PoolHeader>() as u64 + buf * count as u64;
37	    let mut store = vec![Line([0; 64]); bytes.div_ceil(64) as usize];
38	    let mut pool = Pool::init(store.as_mut_slice().as_mut_bytes(), buf as u32, count)
39	        .expect("the store is sized for exactly the segments"); // OK: sized by segment_size and line-aligned
40	    let (prod, cons) = Ring::init(&mut pool, 64, depth, count)
41	        .expect("the pool holds exactly the segments") // OK: count <= MAX_SEGMENTS and depth a power of two
42	        .split();
43	    f(prod, cons)
44	}
45	
46	/// Fill every segment with the consumer idle, then drain in order.
47	/// Returns the segments the producer wrote into and its switches.
48	fn fill(count: u32, depth: u32) -> (u32, u64) {
49	    with_ring(count, depth, |mut prod, mut cons| {
50	        let total = (count * depth) as u64;
51	        let mut used = 1u32 << prod.segment();
52	        for i in 0..total {
53	            let mut slot = prod
54	                .reserve_slot_with::<Msg>(|_| false)
55	                .expect("the ring holds every message"); // OK: total is the ring's capacity
56	            slot.seq = i;
57	            slot.commit();
58	            used |= 1 << prod.segment();
59	        }
60	        assert!(
61	            prod.reserve_slot_with::<Msg>(|_| false).is_err(),
62	            "not full"
63	        );
64	        for i in 0..total {
65	            let msg = cons
66	                .reserve_slot_with::<Msg>(|_| false)
67	                .expect("every message was sent"); // OK: total messages are waiting
68	            assert_eq!(msg.seq, i, "order broken");
69	            msg.release();
70	        }
71	        assert_eq!(cons.switches(), prod.switches(), "switch counts differ");
72	        (used.count_ones(), prod.switches())
73	    })
74	}
