83	                for i in 0..STREAM {
84	                    let mut slot = prod
85	                        .reserve_slot_with::<Msg>(policy::spin)
86	                        .expect("spin never gives up"); // OK: policy::spin never gives up
87	                    slot.seq = i;
88	                    slot.commit();
89	                }
90	                prod.switches()
91	            });
92	            let consumer = s.spawn(move || {
93	                for i in 0..STREAM {
94	                    let msg = cons
95	                        .reserve_slot_with::<Msg>(policy::spin)
96	                        .expect("spin never gives up"); // OK: policy::spin never gives up
97	                    assert_eq!(msg.seq, i, "order broken");
98	                    msg.release();
99	                }
100	                cons.switches()
101	            });
102	            (
103	                producer.join().expect("producer panicked"), // OK: a panic is the run's failure
104	                consumer.join().expect("consumer panicked"), // OK: a panic is the run's failure
105	            )
106	        });
107	        assert_eq!(sent, seen, "switch counts differ");
108	        (sent, start.elapsed().as_secs_f64() * 1e9 / STREAM as f64)
109	    })
110	}
