298	/// Run one measurement cell: pin (or unpin) the calling thread,
299	/// open the fill counters, drive `dur` worth of round trips at
300	/// `flavor` and ring `depth` with the worker on `pin.1`, and
301	/// return probes + counters. The caller's thread affinity is
302	/// left as the cell set it. `segments` is the segmented flavor's
303	/// count per ring, ignored by the others.
304	pub fn run_cell(
305	    flavor: Flavor,
306	    dur: Duration,
307	    pin: Option<(usize, usize)>,
308	    depth: u32,
309	    segments: u32,
310	) -> CellResult {
311	    match pin {
312	        Some((main_cpu, _)) => pin_to_cpu(main_cpu),
313	        None => unpin_current(),
314	    }
315	    #[cfg(target_os = "linux")]
316	    let fills = Fills::open();
317	    let worker = pin.map(|(_, w)| w);
318	    let probes = match flavor {
319	        Flavor::SpscV0 => run_spsc_v0(dur, worker, depth, segments),
320	        Flavor::SpscV1 => run_spsc_v1(dur, worker, depth, segments),
321	        Flavor::SpscV2 => run_spsc_v2(dur, worker, depth, segments),
322	        Flavor::SpscV3 => run_spsc_v3(dur, worker, depth, segments),
323	        Flavor::MpscV0 => run_mpsc_v0(dur, worker, depth),
324	        Flavor::MpscV1 => run_mpsc_v1(dur, worker, depth),
325	    };
326	    #[cfg(target_os = "linux")]
327	    let fills = fills.and_then(Fills::finish);
328	    #[cfg(not(target_os = "linux"))]
329	    let fills = None;
330	    let rts = probes[0].count();
331	    CellResult { probes, rts, fills }
332	}
