334	/// Bind one SPSC ring's `$tx` and `$rx` endpoints, one-line
335	/// slots at `$depth`, the storage held in `$store` (and, for a
336	/// ring of segments, the pool in `$pool`) so it outlives them.
337	///
338	/// - `single $ring, $size`: a ring over one region sized by
339	///   `$size(slot_size, depth)`, `$segments` unused.
340	/// - `segmented`: a v3 ring of `$segments` segments, each
341	///   `$depth` slots, over a pool holding exactly those segments.
342	macro_rules! spsc_pair {
343	    ($tx:ident, $rx:ident, $store:ident, $pool:ident, $depth:expr, $segments:expr,
344	     single $ring:path, $size:path) => {
345	        let _ = $segments;
346	        let slot = CACHE_LINE_SIZE as u32;
347	        let mut $store = LineBuf::new($size(slot, $depth));
348	        let (mut $tx, mut $rx) = <$ring>::init($store.as_mut_bytes(), slot, $depth)
349	            .unwrap() // OK: the region is sized by the ring's own size function and line-aligned
350	            .split();
351	    };
352	    ($tx:ident, $rx:ident, $store:ident, $pool:ident, $depth:expr, $segments:expr, segmented) => {
353	        let slot = CACHE_LINE_SIZE as u32;
354	        let buf = zc_ring_x1::spsc::v3::segment_size(slot, $depth);
355	        let mut $store = LineBuf::new(
356	            size_of::<zc_ring_x1::PoolHeader>() as u64 + buf * $segments as u64,
357	        );
358	        let mut $pool = zc_ring_x1::Pool::init($store.as_mut_bytes(), buf as u32, $segments)
359	            .unwrap(); // OK: the region is sized for exactly the segments and line-aligned
360	        let (mut $tx, mut $rx) = zc_ring_x1::spsc::v3::Ring::init(&mut $pool, slot, $depth, $segments)
361	            .unwrap() // OK: the pool holds exactly the segments, sized by segment_size
362	            .split();
363	    };
364	}
365	
366	/// Define an SPSC cell body over the ring pair `$pair` builds (see
367	/// `spsc_pair`): two rings, both ends `reserve_slot_with` under
368	/// the [`spin`] policy (recv sites instrumented). The SPSC
369	/// versions share the endpoint surface and differ by path, so one
370	/// body serves them all and the A/B measures the protocol alone.
371	macro_rules! spsc_cell {
372	    ($name:ident, $flavor:expr, $($pair:tt)+) => {
373	        fn $name(
374	            dur: Duration,
375	            worker_cpu: Option<usize>,
376	            depth: u32,
377	            segments: u32,
378	        ) -> [TProbe; 8] {
379	            spsc_pair!(req_tx, req_rx, req_store, req_pool, depth, segments, $($pair)+);
380	            spsc_pair!(resp_tx, resp_rx, resp_store, resp_pool, depth, segments, $($pair)+);
381	
382	            std::thread::scope(|s| {
383	                let worker = s.spawn(move || {
384	                    if let Some(cpu) = worker_cpu {
385	                        pin_to_cpu(cpu);
386	                    }
387	                    let mut recv = RecvProbes::new($flavor, "worker");
388	                    let mut send_probe = TProbe::new(&format!(
389	                        "{} worker send (reserve+commit)",
390	                        $flavor.as_str()
391	                    ));
392	                    loop {
393	                        let v = instrumented_recv(&mut recv, |attempts, spin_start| {
394	                            let slot = req_rx
395	                                .reserve_slot_with::<u64>(|a| {
396	                                    if a == 0 {
397	                                        *spin_start = ticks::read_ticks();
398	                                    }
399	                                    *attempts = a + 1;
400	                                    core::hint::spin_loop();
401	                                    true
402	                                })
403	                                .expect("spin never gives up");
404	                            let v = *slot;
405	                            slot.release();
406	                            v
407	                        });
408	                        if v == STOP {
409	                            break;
410	                        }
411	                        let s = ticks::read_ticks();
412	                        let mut slot = resp_tx
413	                            .reserve_slot_with::<u64>(spin)
414	                            .expect("spin never gives up");
415	                        *slot = v;
416	                        slot.commit();
417	                        send_probe.record(ticks::read_ticks().wrapping_sub(s));
418	                    }
419	                    (recv, send_probe)
420	                });
421	
422	                let mut send_probe =
423	                    TProbe::new(&format!("{} main send (reserve+commit)", $flavor.as_str()));
424	                let mut recv = RecvProbes::new($flavor, "main");
425	                drive(
426	                    dur,
427	                    |v| {
428	                        let s = ticks::read_ticks();
429	                        let mut slot = req_tx
430	                            .reserve_slot_with::<u64>(spin)
431	                            .expect("spin never gives up");
432	                        *slot = v;
433	                        slot.commit();
434	                        send_probe.record(ticks::read_ticks().wrapping_sub(s));
435	                    },
436	                    || {
437	                        instrumented_recv(&mut recv, |attempts, spin_start| {
438	                            let slot = resp_rx
439	                                .reserve_slot_with::<u64>(|a| {
440	                                    if a == 0 {
441	                                        *spin_start = ticks::read_ticks();
442	                                    }
443	                                    *attempts = a + 1;
444	                                    core::hint::spin_loop();
445	                                    true
446	                                })
447	                                .expect("spin never gives up");
448	                            let v = *slot;
449	                            slot.release();
450	                            v
451	                        })
452	                    },
453	                );
454	                let mut slot = req_tx
455	                    .reserve_slot_with::<u64>(spin)
456	                    .expect("spin never gives up");
457	                *slot = STOP;
458	                slot.commit();
459	                let (worker_recv, worker_send) = worker.join().expect("worker panicked");
460	                [
461	                    send_probe,
462	                    worker_recv.phase,
463	                    worker_recv.spin,
464	                    worker_recv.attempts,
465	                    worker_send,
466	                    recv.phase,
467	                    recv.spin,
468	                    recv.attempts,
469	                ]
470	            })
471	        }
472	    };
