    dur: Duration,
    pin: Option<(usize, usize)>,
    depth: u32,
    segments: u32,
) -> CellResult {
    match pin {
        Some((main_cpu, _)) => pin_to_cpu(main_cpu),
        None => unpin_current(),
    }
