        Flavor::SpscV1 => run_spsc_v1(dur, worker, depth, segments),
        Flavor::SpscV2 => run_spsc_v2(dur, worker, depth, segments),
        Flavor::SpscV3 => run_spsc_v3(dur, worker, depth, segments),
        Flavor::MpscV0 => run_mpsc_v0(dur, worker, depth),
