macro_rules! spsc_stream {
    ($name:ident, $($pair:tt)+) => {
        fn $name(
            dur: Duration,
            pin: Option<(usize, usize)>,
            depth: u32,
            segments: u32,
        ) -> (u64, f64, Option<u64>) {
            spsc_pair!(tx, rx, store, pool, depth, segments, $($pair)+);
            let start = Instant::now();
            let msgs = std::thread::scope(|s| {
                s.spawn(move || {
                    if let Some((p, _)) = pin {
                        pin_to_cpu(p);
                    }
                    let mut counter: u64 = 0;
                    loop {
                        for _ in 0..STREAM_CHECK_EVERY {
                            let mut slot = tx
                                .reserve_slot_with::<u64>(zc_ring_x1::policy::spin)
                                .expect("spin never gives up");
                            *slot = counter;
                            slot.commit();
                            counter += 1;
                        }
                        if start.elapsed() >= dur {
                            break;
                        }
                    }
                    let mut slot = tx
                        .reserve_slot_with::<u64>(zc_ring_x1::policy::spin)
                        .expect("spin never gives up");
                    *slot = STOP;
                    slot.commit();
                });
                let consumer = s.spawn(move || {
                    if let Some((_, c)) = pin {
                        pin_to_cpu(c);
                    }
                    drain_stream(|| {
                        let slot = rx
                            .reserve_slot_with::<u64>(zc_ring_x1::policy::spin)
                            .expect("spin never gives up");
                        let v = *slot;
                        slot.release();
                        v
                    })
                });
                consumer.join().expect("consumer panicked")
            });
            (msgs, start.elapsed().as_secs_f64())
        }
    };
}

