cat > tmp/sweep_compare.py <<'EOF'
import re, sys
def rows(path):
    out={}
    hdr=None
    for line in open(path):
        if not line.startswith('|') or line.startswith('|--'): continue
        cells=[c.strip() for c in line.strip().strip('|').split('|')]
        if cells[0]=='placement': hdr=cells; continue
        if hdr: out[(cells[0],cells[1],cells[2])]=dict(zip(hdr,cells))
    return out
def num(v):
    v=v.split('/')[0].rstrip('M')
    try: return float(v)
    except: return None
for m in ['3900x','7600x']:
    for kind,cols in [('stream',['ns/msg','xfills/msg','switches/msg']),('matrix',['m.send','w.recv','w.send','m.recv','xfills/RT','switches/RT'])]:
        a=rows(f'tmp/sweep-{m}/{kind}-1.md'); b=rows(f'tmp/sweep-{m}/{kind}-2.md')
        print(f'\n=== {m} {kind}: v2 vs v3, run1 (run2)')
        print('| placement | depth | ' + ' | '.join(f'{c} v2 | {c} v3' for c in cols) + ' |')
        places=sorted({k[0] for k in a}, key=lambda p: list(dict.fromkeys(k[0] for k in a)).index(p))
        maxdev=0
        for p in places:
            for d in ['1','8','64','1024']:
                r=[p,d]
                for c in cols:
                    for f in ['spsc-v2','spsc-v3']:
                        k=(p,f,d)
                        if k not in a: r.append('?'); continue
                        x=num(a[k][c]); y=num(b[k][c]) if k in b else None
                        if x is None: r.append(a[k][c]); continue
                        if y not in (None,0) and x and c.startswith(('ns','m.','w.')):
                            maxdev=max(maxdev,abs(x-y)/max(x,y))
                        r.append(f'{a[k][c].split("/")[0]} ({b[k][c].split("/")[0] if k in b else "?"})')
                print('| '+' | '.join(r)+' |')
        print(f'max run1/run2 deviation in time cells: {maxdev*100:.0f}%')
EOF
