1	//! tp-pool: run the pool-message loop over every placement,
2	//! flavor, ring depth, and pool size, each cell for a duration,
3	//! and emit one ns-per-message table per placement,
4	//! the pool sizes as columns and the flavor-by-depth rows, with
5	//! the fill counters beside it. The descriptor rings sweep
6	//! their depth, and the cordyceps row, an unbounded intrusive
7	//! queue, has none.
8	
9	use std::time::Duration;
10	
11	use clap::Parser;
12	
13	use tp_matrix::pool::{POOL_FLAVORS, PoolFlavor, PoolResult, run_pool_cell};
14	use tp_matrix::{PLACEMENT_MEANING, XFILLS_MEANING, print_legend};
15	use tp_runner::parse_depth;
16	use tp_runner::topo::{Placement, discover_placements};
17	
18	/// Banner: name, version, and tagline on one line, the first
19	/// line of every run and of `-h`/`--help`.
20	const TOP_ABOUT: &str = concat!(
21	    "tp-pool ",
22	    env!("CARGO_PKG_VERSION"),
23	    " (zc-ring-x1 ",
24	    env!("ZC_RING_X1_VERSION"),
25	    ")",
26	    " - run the pool-message sweep, one table per placement"
27	);
28	
29	/// The tp-pool CLI.
30	#[derive(Parser, Debug)]
31	#[command(
32	    name = "tp-pool",
33	    version = concat!(env!("CARGO_PKG_VERSION"), " (zc-ring-x1 ", env!("ZC_RING_X1_VERSION"), ")"),
34	    about = TOP_ABOUT,
35	    max_term_width = 80
36	)]
37	struct Cli {
38	    /// Pool sizes (buffers preallocated) to run, comma-separated,
39	    /// each a column
40	    ///
41	    /// The pool bounds the messages in flight, so this is the
42	    /// axis every flavor shares. Any count from 1 up.
43	    #[arg(
44	        long,
45	        value_name = "LIST",
46	        value_delimiter = ',',
47	        default_value = "1,100,1000",
48	        value_parser = parse_pool
49	    )]
50	    pool: Vec<u32>,
51	
52	    /// Ring depths (slots per ring) for the ring flavors,
53	    /// comma-separated powers of two, each a row per flavor
54	    ///
55	    /// A depth at or above the pool size never reports Full,
56	    /// so that row is the ring at the pool's bound and the rows
57	    /// below it are the ring throttling first.
58	    #[arg(
59	        long,
60	        value_name = "LIST",
61	        value_delimiter = ',',
62	        default_value = "1,8,64,1024",
63	        value_parser = parse_depth
64	    )]
65	    depth: Vec<u32>,
66	
67	    /// Wall-clock seconds per cell run
68	    #[arg(
69	        short = 'd',
70	        long = "duration",
71	        value_name = "SECS",
72	        default_value_t = 0.1,
73	        value_parser = parse_duration
74	    )]
75	    duration: f64,
76	
77	    /// Runs per cell, the median reported
78	    #[arg(long, value_name = "N", default_value_t = 3, value_parser = parse_repeat)]
79	    repeat: usize,
80	
81	    /// Print a legend after the last placement explaining every
82	    /// table and column
83	    #[arg(short = 'v', long)]
84	    verbose: bool,
85	}
86	
87	/// clap value parser for one `--pool` element: a count from 1
88	/// up.
89	fn parse_pool(s: &str) -> Result<u32, String> {
90	    let n: u32 = s.parse().map_err(|e| format!("{s}: {e}"))?;
91	    if n == 0 {
92	        return Err("pool size must be at least 1".to_string());
93	    }
94	    Ok(n)
95	}
96	
97	/// clap value parser for `--duration`: seconds above zero.
98	fn parse_duration(s: &str) -> Result<f64, String> {
99	    let secs: f64 = s.parse().map_err(|e| format!("{s}: {e}"))?;
100	    if !(secs > 0.0 && secs.is_finite()) {
101	        return Err("duration must be a number of seconds above 0".to_string());
102	    }
103	    Ok(secs)
104	}
105	
106	/// clap value parser for `--repeat`: a count from 1 up.
107	fn parse_repeat(s: &str) -> Result<usize, String> {
108	    let n: usize = s.parse().map_err(|e| format!("{s}: {e}"))?;
109	    if n == 0 {
110	        return Err("repeat must be at least 1".to_string());
111	    }
112	    Ok(n)
113	}
114	
115	/// One row of the tables: a flavor at a depth (`None` for the
116	/// depthless cordyceps row).
117	struct Row {
118	    flavor: PoolFlavor,
119	    depth: Option<u32>,
120	}
121	
122	/// The rows in table order: each ring flavor at every depth,
123	/// then the depthless ones.
124	fn rows(depths: &[u32]) -> Vec<Row> {
125	    let mut rows = Vec::new();
126	    for flavor in POOL_FLAVORS {
127	        if flavor.has_depth() {
128	            for &depth in depths {
129	                rows.push(Row {
130	                    flavor,
131	                    depth: Some(depth),
132	                });
133	            }
134	        } else {
135	            rows.push(Row {
136	                flavor,
137	                depth: None,
138	            });
139	        }
140	    }
141	    rows
142	}
143	
144	/// Run one cell `repeat` times and keep the median by ns per
145	/// message, its fill counters with it.
146	fn median_cell(
147	    flavor: PoolFlavor,
148	    pin: Option<(usize, usize)>,
149	    pool_size: u32,
150	    depth: u32,
151	    dur: Duration,
152	    repeat: usize,
153	) -> PoolResult {
154	    let mut runs: Vec<PoolResult> = (0..repeat)
155	        .map(|_| run_pool_cell(flavor, pin, pool_size, depth, dur))
156	        .collect();
157	    runs.sort_by(|a, b| ns_per_msg(a).total_cmp(&ns_per_msg(b)));
158	    runs.swap_remove(runs.len() / 2)
159	}
