162	/// The first two columns left-aligned, the rest right-aligned.
163	/// Returns the table's width in characters.
164	fn print_table(headers: &[String], rows: &[Vec<String>]) -> usize {
165	    let mut w: Vec<usize> = headers.iter().map(|h| h.len()).collect();
166	    for row in rows {
